// 개념 예시: 항공기 키 설계
type Aircraft = {
  msn: string;          // primary key: 바뀌지 않음
  registration: string; // title key: 사람이 읽는 이름
  model: string;
  flightHours: number;
};

// 개념 예시: 링크를 뒷받침하는 데이터
// 다:1 — 작업지시에 외래 키
type WorkOrder = { woId: string; aircraftMsn: string };
// 다:다 — 조인 데이터셋 한 행 = 링크 하나
type WoTechnician = { woId: string; techId: string };

@prefix ex: <http://example.org/> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
ex:A321 rdfs:subClassOf ex:Aircraft .
ex:HL8001 a ex:A321 .
# 추론기: HL8001 은 Aircraft 다 (적지 않아도)
